package com.example.lending;

import com.fasterxml.jackson.databind.JsonNode;
import com.fasterxml.jackson.databind.ObjectMapper;
import org.junit.jupiter.api.Test;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.boot.test.autoconfigure.web.servlet.AutoConfigureMockMvc;
import org.springframework.boot.test.context.SpringBootTest;
import org.springframework.http.MediaType;
import org.springframework.test.web.servlet.MockMvc;

import java.util.Map;
import java.util.UUID;

import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.get;
import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.post;
import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.jsonPath;
import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.status;

@SpringBootTest
@AutoConfigureMockMvc
class AuditLogIntegrationTest {

    @Autowired
    MockMvc mockMvc;

    @Autowired
    ObjectMapper objectMapper;

    @Test
    void audit_for_unknown_target_is_empty_array() throws Exception {
        mockMvc.perform(get("/audit").param("targetId", UUID.randomUUID().toString()))
                .andExpect(status().isOk())
                .andExpect(jsonPath("$.length()").value(0));
    }

    @Test
    void loan_and_return_are_recorded_against_the_loan_in_time_order() throws Exception {
        String memberId = registerMember();
        String bookId = registerBook("Audit Loan");
        String loanId = loanBook(bookId, memberId);

        mockMvc.perform(post("/loans/{loanId}/return", loanId)).andExpect(status().isOk());

        mockMvc.perform(get("/audit").param("targetId", loanId))
                .andExpect(status().isOk())
                .andExpect(jsonPath("$.length()").value(2))
                .andExpect(jsonPath("$[0].action").value("LOAN"))
                .andExpect(jsonPath("$[0].targetId").value(loanId))
                .andExpect(jsonPath("$[0].memberId").value(memberId))
                .andExpect(jsonPath("$[0].occurredAt").isString())
                .andExpect(jsonPath("$[1].action").value("RETURN"))
                .andExpect(jsonPath("$[1].targetId").value(loanId))
                .andExpect(jsonPath("$[1].memberId").value(memberId));
    }

    @Test
    void rejected_second_return_does_not_add_a_record() throws Exception {
        String memberId = registerMember();
        String loanId = loanBook(registerBook("Audit Double Return"), memberId);
        mockMvc.perform(post("/loans/{loanId}/return", loanId)).andExpect(status().isOk());
        mockMvc.perform(post("/loans/{loanId}/return", loanId)).andExpect(status().isConflict());

        mockMvc.perform(get("/audit").param("targetId", loanId))
                .andExpect(jsonPath("$.length()").value(2))
                .andExpect(jsonPath("$[1].action").value("RETURN"));
    }

    @Test
    void discard_is_recorded_against_the_book_with_null_member_id() throws Exception {
        String bookId = registerBook("Audit Discard");
        mockMvc.perform(post("/books/{id}/discard", bookId)).andExpect(status().isOk());

        mockMvc.perform(get("/audit").param("targetId", bookId))
                .andExpect(status().isOk())
                .andExpect(jsonPath("$.length()").value(1))
                .andExpect(jsonPath("$[0].action").value("DISCARD"))
                .andExpect(jsonPath("$[0].targetId").value(bookId))
                .andExpect(jsonPath("$[0].memberId").doesNotExist());
    }

    @Test
    void repeated_discard_does_not_add_a_record() throws Exception {
        String bookId = registerBook("Audit Twice Discard");
        mockMvc.perform(post("/books/{id}/discard", bookId)).andExpect(status().isOk());
        mockMvc.perform(post("/books/{id}/discard", bookId)).andExpect(status().isOk());

        mockMvc.perform(get("/audit").param("targetId", bookId))
                .andExpect(jsonPath("$.length()").value(1));
    }

    @Test
    void suspend_and_unsuspend_are_recorded_against_the_member() throws Exception {
        String memberId = registerMember();
        mockMvc.perform(post("/members/{memberId}/suspend", memberId)).andExpect(status().isOk());
        mockMvc.perform(post("/members/{memberId}/suspend", memberId)).andExpect(status().isOk());
        mockMvc.perform(post("/members/{memberId}/unsuspend", memberId)).andExpect(status().isOk());

        mockMvc.perform(get("/audit").param("targetId", memberId))
                .andExpect(status().isOk())
                .andExpect(jsonPath("$.length()").value(2))
                .andExpect(jsonPath("$[0].action").value("SUSPEND"))
                .andExpect(jsonPath("$[0].targetId").value(memberId))
                .andExpect(jsonPath("$[0].memberId").value(memberId))
                .andExpect(jsonPath("$[1].action").value("UNSUSPEND"))
                .andExpect(jsonPath("$[1].targetId").value(memberId))
                .andExpect(jsonPath("$[1].memberId").value(memberId));
    }

    @Test
    void rejected_loan_for_suspended_member_leaves_no_loan_record() throws Exception {
        String memberId = registerMember();
        String bookId = registerBook("Audit Blocked Loan");
        mockMvc.perform(post("/members/{memberId}/suspend", memberId)).andExpect(status().isOk());
        mockMvc.perform(post("/loans").contentType(MediaType.APPLICATION_JSON)
                        .content(loanBody(bookId, memberId)))
                .andExpect(status().isConflict());

        mockMvc.perform(get("/audit").param("targetId", bookId))
                .andExpect(jsonPath("$.length()").value(0));
    }

    private String registerMember() throws Exception {
        String response = mockMvc.perform(post("/members")
                        .contentType(MediaType.APPLICATION_JSON)
                        .content("{\"name\":\"감사테스트\"}"))
                .andExpect(status().isCreated())
                .andReturn().getResponse().getContentAsString();
        return objectMapper.readTree(response).get("memberId").asText();
    }

    private String registerBook(String title) throws Exception {
        String response = mockMvc.perform(post("/books")
                        .contentType(MediaType.APPLICATION_JSON)
                        .content(objectMapper.writeValueAsString(Map.of("title", title))))
                .andExpect(status().isCreated())
                .andReturn().getResponse().getContentAsString();
        JsonNode book = objectMapper.readTree(response);
        return book.get("id").asText();
    }

    private String loanBook(String bookId, String memberId) throws Exception {
        String response = mockMvc.perform(post("/loans").contentType(MediaType.APPLICATION_JSON)
                        .content(loanBody(bookId, memberId)))
                .andExpect(status().isCreated())
                .andReturn().getResponse().getContentAsString();
        return objectMapper.readTree(response).get("loanId").asText();
    }

    private String loanBody(String bookId, String memberId) throws Exception {
        return objectMapper.writeValueAsString(Map.of("bookId", bookId, "memberId", memberId));
    }
}

